CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TABLE offer_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug varchar(40) NOT NULL UNIQUE, display_name varchar(80) NOT NULL, sort_order int NOT NULL DEFAULT 0, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE businesses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_user_id uuid NOT NULL UNIQUE, name varchar(120) NOT NULL, slug varchar(140) NOT NULL UNIQUE, description text, phone varchar(30), email citext, logo_url text, cover_url text, vat_number varchar(40), rating_avg numeric(3,2) NOT NULL DEFAULT 0, rating_count int NOT NULL DEFAULT 0, is_verified boolean NOT NULL DEFAULT false, status varchar(20) NOT NULL DEFAULT 'ACTIVE', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, version bigint NOT NULL DEFAULT 0,
 CONSTRAINT fk_business_owner FOREIGN KEY(owner_user_id) REFERENCES users(id), CONSTRAINT ck_business_rating CHECK(rating_avg BETWEEN 0 AND 5 AND rating_count>=0));
CREATE TABLE business_locations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL, label varchar(80), address_line1 varchar(255) NOT NULL, address_line2 varchar(255), city varchar(120) NOT NULL, postal_code varchar(20), country_code char(2) NOT NULL, latitude numeric(9,6) NOT NULL, longitude numeric(9,6) NOT NULL, location geography(Point,4326) GENERATED ALWAYS AS (ST_SetSRID(ST_MakePoint(longitude::double precision,latitude::double precision),4326)::geography) STORED, is_primary boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 CONSTRAINT fk_location_business FOREIGN KEY(business_id) REFERENCES businesses(id), CONSTRAINT ck_business_coordinates CHECK(latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180), CONSTRAINT uq_location_business UNIQUE(id,business_id));
CREATE INDEX ix_locations_business ON business_locations(business_id);
CREATE UNIQUE INDEX uq_primary_location ON business_locations(business_id) WHERE is_primary;
CREATE TABLE offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL, location_id uuid NOT NULL, category_id uuid NOT NULL, title varchar(120) NOT NULL, description text, image_url text, original_price numeric(10,2) NOT NULL, price numeric(10,2) NOT NULL, currency char(3) NOT NULL DEFAULT 'EUR', quantity_total int NOT NULL, quantity_available int NOT NULL, pickup_start_at timestamptz NOT NULL, pickup_end_at timestamptz NOT NULL, status varchar(20) NOT NULL DEFAULT 'ACTIVE', published_at timestamptz, paused_at timestamptz, sold_out_at timestamptz, expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, version bigint NOT NULL DEFAULT 0,
 CONSTRAINT fk_offer_business FOREIGN KEY(business_id) REFERENCES businesses(id), CONSTRAINT fk_offer_location FOREIGN KEY(location_id,business_id) REFERENCES business_locations(id,business_id), CONSTRAINT fk_offer_category FOREIGN KEY(category_id) REFERENCES offer_categories(id),
 CONSTRAINT ck_offer_price CHECK(price>0 AND original_price>=price), CONSTRAINT ck_offer_stock CHECK(quantity_total>0 AND quantity_available BETWEEN 0 AND quantity_total), CONSTRAINT ck_offer_pickup CHECK(pickup_end_at>pickup_start_at), CONSTRAINT ck_offer_status CHECK(status IN ('ACTIVE','PAUSED','SOLD_OUT','EXPIRED')));
CREATE INDEX ix_offer_business_status ON offers(business_id,status);
CREATE INDEX ix_offer_location ON offers(location_id,business_id);
CREATE INDEX ix_offer_category ON offers(category_id);
CREATE INDEX ix_offer_pickup ON offers(pickup_end_at);
